def hypercube_betti1(n):
    return n * 2**(n-1) - 2**n + 1 if n > 0 else 0

print(f'{"n":>3} | {"Vertices":>8} | {"Edges":>8} | {"β₁":>8}')
print('-' * 38)
for n in range(1, 11):
    print(f'{n:>3} | {2**n:>8} | {n*2**(n-1):>8} | {hypercube_betti1(n):>8}')

assert hypercube_betti1(2) == 1
for n in range(3, 11):
    assert hypercube_betti1(n) > 1
print('\n✓ β₁(Q₂)=1, β₁(Qₙ)>1 for n≥3')
